reaction_source.text:
{notneeded_react}
increment erasedCount
[PlaySound2D(Quince_Resume_World)]
if not dead(othello) && IsCharacterHere(othello):
    //[LookAt(othello,ophelia)]
    if not believes(othello,demon):
        othello: [sad] "What on <i>earth?</i>"
    endif
    [<Suppress(6004)>]
    assert believes(othello,demon)
endif
if not dead(guildenstern) && IsCharacterHere(guildenstern):
    //[LookAt(guildenstern,ophelia)]
    if not believes(guildenstern,demon):
        guildenstern: [surprise] "Ugh-- Waaah! What's happening?!"
    endif
    [<Suppress(6004)>]
    assert believes(guildenstern,demon)
endif
if not dead(rosencrantz) && IsCharacterHere(rosencrantz):
    //[LookAt(rosencrantz,ophelia)]
    if not believes(rosencrantz,demon):
        rosencrantz: "This cannot be real."
    endif
    [<Suppress(6004)>]
    assert believes(rosencrantz,demon)
endif
if not dead(horatio) && IsCharacterHere(horatio):
    //[LookAt(horatio,ophelia)]
    if not believes(horatio,demon):
        horatio: [afraid] "What <i>was</i> that? O-oh..."
    endif
    [<Suppress(6004)>]
    assert believes(horatio,demon)
endif
if not dead(irma) && IsCharacterHere(irma):
    //[LookAt(irma,ophelia)]
    if not believes(irma,demon):
        irma: [afraid] "Ophelia? Did-- did <i>you</i> do that?"
    endif
    [<Suppress(6004)>]
    assert believes(irma,demon)
endif
if not dead(brit) && IsCharacterHere(brit):
    //[LookAt(brit,ophelia)]
    if not believes(brit,demon):
        brit: [afraid] "What have you done, Ophelia? What <i>was that</i>?"
    endif
    [<Suppress(6004)>]
    assert believes(brit,demon)
endif
if not dead(marcellus) && IsCharacterHere(marcellus):
    //[LookAt(marcellus,ophelia)]
    if not believes(marcellus,demon):
        marcellus: "Oy! I-is-- wos that-- what just-- Ophelia?"
    endif
    [<Suppress(6004)>]
    assert believes(marcellus,demon)
endif
if not dead(bernardo) && IsCharacterHere(bernardo):
    //[LookAt(bernardo,ophelia)]
    if not believes(bernardo,demon):
        bernardo: [surprise] "What in God's name..."
    endif
    [<Suppress(6004)>]
    assert believes(bernardo,demon)
endif
if not dead(laertes) && IsCharacterHere(laertes):
    //[LookAt(laertes,ophelia)]
    if not believes(laertes,demon):
        laertes: "Ophelia? What <b>was</b> that? What did you <b>do?</b>"
    endif
    [<Suppress(6004)>]
    assert believes(laertes,demon)
endif
if not dead(gertrude) && IsCharacterHere(gertrude):
    //[LookAt(gertrude,ophelia)]
    if not believes(gertrude,demon):
        gertrude: [surprise] "W-what?"
        gertrude: [despair] "What am I <i>seeing?</i> Ophelia...?"
    endif
    [<Suppress(6004)>]
    assert believes(gertrude,demon)
endif
if not dead(claudius) && IsCharacterHere(claudius):
    //[LookAt(claudius,ophelia)]
    if not believes(claudius,demon):
        claudius: "What is this? What's happening?"
    endif
    [<Suppress(6004)>]
    assert believes(claudius,demon)
endif
if not dead(hamlet) && IsCharacterHere(hamlet):
    //[LookAt(hamlet,ophelia)]
    if not believes(hamlet,demon):
        hamlet: [afraid] "Ophelia? You're... some kind of..."
        hamlet: [afraid] "No. What <b>are</b> you?"
    endif
    [<Suppress(6004)>]
    assert believes(hamlet,demon)
endif
if not dead(polonius) && IsCharacterHere(polonius):
    //[LookAt(polonius,ophelia)]
    if not believes(polonius,demon):
        if hasSeen(polonius,Responsible):
            polonius: [afraid] "Oh god. <i>It's true.</i>"
        else:
            polonius: [afraid] "O-Ophelia?"
        endif
    endif
    [<Suppress(6004)>]
    assert believes(polonius,demon)
endif
//Ophelia's own progressing reactions
if (erasedCountPersistent = 0):
    [noblock Play(ophelia,am_rub_brow)]
    ophelia: [surprise] {Gasp} "What? What just..."
    ophelia: [sad] "That was <i>me?</i> I did <i>that?</i>"
    [Play(ophelia,am_neutral)]
    ophelia: [angry] {Disgust} "Quince tricked me, again. This isn't a gift. This is something horrifying."
    ophelia: [sad] "I shouldn't use this. I should just reset this world and leave. I can't stay here."
    [noblock Play(ophelia,am_denial)]
    ophelia: [angry] {Im_Not_Like_Him} "I'm... I'm not a killer. I'm not like <i>him.</i>"
    assert ownedInformation(Responsible)
elif (erasedCountPersistent < 6):
    if FlipCoin():
        ophelia: [sad] "This is evil, this power."
    else:
        ophelia: [sad] "It doesn't matter if they'll return in the next world. This is wrong."
    endif
elif (erasedCountPersistent < 12):
    if FlipCoin():
        if FlipCoin():
            [noblock Play(ophelia,am_shrug)]
            ophelia: [sad] "It's almost like a little game. Watch them run, seek them out--"
            [noblock Play(ophelia,am_rub_brow)]
            ophelia: [despair] "No. What am I <i>saying?</i>"
        else:
            [noblock Play(ophelia,am_fold_arms)]
            ophelia: [sad] "Why do I continue this? I could stop. I <i>ought</i> to stop. I could reset this world."
        endif
    else:
        if FlipCoin():
            ophelia: "..."
        else:
            [noblock Play(ophelia,am_think)]
            ophelia: {Its_So_Easy} "It's so easy. They don't even feel real."
        endif
    endif
elif (erasedCountPersistent = 13):
    [noblock Play(ophelia,am_rub_brow)]
    [noblock Play(ophelia,am_shake_head)]
    ophelia: [sad] {I_Know_Sad} "I know it's <b>not too late to turn back.</b> To reset. To leave. But I've wrought so much."
    ophelia: [happy] "This is sort of fun, in a sick way, isn't it? A way to play with them."
    [noblock Play(ophelia,am_neutral)]
    ophelia: [happy] "Besides, I can revive them any time I like. They won't remember a thing."
elif (erasedCountPersistent = 14):
    [noblock Play(ophelia,am_fold_arms)]
    ophelia: [happy] {Chuckle} "They all looked down on me. I was just some nothing girl to them."
    ophelia: [happy] "Perhaps now I desire their fear. Crave it."
    [noblock Play(ophelia,am_think)]
    ophelia: [happy] "Or -- perhaps this is merely a tool I can use to amuse myself."
    ophelia: [happy] "Either way, I <i>clearly</i> have no desire to give it up."
    [Play(ophelia,am_neutral)]
    ophelia: [happy] {Cannot_Be_Undone} "What's done cannot be undone."
elif (erasedCountPersistent = 15):
    ophelia: "..."
    [Play(ophelia,am_bury_head)]
    ophelia: [awkward] {Losing_It_1} "I think something must have gone a bit broken in my head. Hee, hee..."
    ophelia: [happy] {Losing_It_2} "Every time I kill one, I feel the strangest sense of satisfaction."
    [Play(ophelia,am_stand)]
    ophelia: [smile] {Losing_It_3} "Yes, if they're <b>all dead, I can tell something marvelous will happen!</b>"
    [noblock Play(ophelia,am_theatrical2)]
    ophelia: [smile] {Losing_It_4} "I'll truly have <b>won</b> then!"
else:
    if FlipCoin():
        if FlipCoin():
            [noblock Play(ophelia,am_shake_head)]
            ophelia: [disgust] {Disgust} "What an ugly way to die."
        else:
            [noblock Play(ophelia,am_shrug)]
            ophelia: [disgust] {Too_Simple_Evil} "Too simple."
        endif
    else:
        if FlipCoin():
            [noblock Play(ophelia,am_think)]
            ophelia: [happy] "..."
        else:
            [noblock Play(ophelia,am_nod)]
            ophelia: {Die} "Yes. Die."
        endif
    endif
endif
increment erasedCountPersistent
